# Dated investment/counterparty governance; separate from recipe loss horizons.
if(!exists('compile_credit_decision_policy'))library(creditratingsystem)
run_structured_governance<-function(data=NULL,verify_reference=TRUE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/structured_governance.json',package='creditratingsystem'),simplifyVector=FALSE);out<-list()
 for(product in names(data$variants)){
 case<-data$variants[[product]];sid<-case$subject_id;stype<-case$subject_type;model<-case$model;D<-'2024-01-01';tables<-setNames(list(list(list(subject_id=sid,version='1',effective_from=D,effective_to=NULL,known_at=D,attributes=list(product=product)))),stype);subjects<-build_rating_subjects(tables,list(),D,D)$value;route<-route_rating_profile(case$snapshot,case$rules,D,D)$value;applicability<-assess_rating_applicability(case$snapshot,case$applicability_contract,D,D)$value
 registry<-register_rating_model_version(NULL,list(model=model,dependencies=setNames(list(),character()),configuration=list(source_recipe_reference=case$source_recipe_reference)),list(model_id=model$model_id,model_version='v1',registered_at='2023-12-31'))$value;mh<-registry$entries[[1]]$model_hash;assignment<-list(list(assignment_id=paste0(product,'-champion'),profile_id=route$profile_id,purpose='PD',model_id=model$model_id,model_version='v1',model_hash=mh,effective_from=D,effective_to='2025-01-01',known_at='2023-12-31'));selected<-select_effective_model(registry,assignment,route$profile_id,'PD','2024-01-15','2024-01-15')$value
 request<-list(row_id=product,known_at=D,model_id=model$model_id,model_version='v1',model_hash=mh,recipe=list(method='binary_glm',version='1.0',parameters=list(expected_target=model$target)),input=list(X=list(list(0)),feature_order=list('x')));batch<-rate_subject_batch(list(request),registry,paste0(product,'-origin'),D)$value;pd<-batch$rows[[1]]$value[[1]];subject<-list(subject_id=sid,subject_type=stype);components<-list(c(list(component_id=paste0(product,'-pd'),quantity='PD',value=pd),subject,list(variant='independent_30day_monitor',definition=model$target)));binding<-list(profile_id=route$profile_id,profile_version='1',model_id=model$model_id,model_version='v1',model_hash=mh,input_hash=batch$rows[[1]]$input_hash);assessment<-compose_risk_assessment(paste0(product,'-governance'),subject,components,binding,D,D,D)$value
 contract<-case$policy$approval_contract;timing<-list(as_of=D,known_at=D);decision_inputs<-list(risk=c(timing,list(pd=pd,target=model$target,freshness='CURRENT')),affordability=c(timing,list(status='NOT_APPLICABLE',domain=contract$domain,applicability_reference=contract$affordability$reference,valid_until='2024-02-01')),eligibility=c(timing,list(status='ELIGIBLE')),operations=c(timing,list(status='CLEAR',legal_status='VERIFIED')),as_of=D,known_at=D);policy<-compile_credit_decision_policy(case$policy)$value;decision<-do.call(apply_credit_decision_policy,c(list(policy=policy),decision_inputs))$value;invalid<-decision_inputs;invalid$operations$legal_status<-'UNVERIFIED';blocked<-do.call(apply_credit_decision_policy,c(list(policy=policy),invalid))$value
 freshness_policy<-list(maximum_age_days=30,maximum_information_age_days=30,trigger_types=list('payment_delay'));fresh<-check_assessment_freshness(assessment,freshness_policy,list(),'2024-01-15','2024-01-15')$value;performing_assessment<-compose_risk_assessment(paste0(product,'-performing'),subject,components,binding,'2024-01-15','2024-01-15','2024-01-15')$value;trigger<-list(event_id=paste0(product,'-arrears'),subject_id=sid,type='payment_delay',occurred_at='2024-01-15',known_at='2024-01-16');stale<-check_assessment_freshness(assessment,freshness_policy,list(trigger),'2024-01-16','2024-01-16')$value;dependency<-list(list(assessment_id=assessment$assessment_id,dependency_type=stype,dependency_id=sid));event<-list(event_id=trigger$event_id,revision='1',occurred_at=trigger$occurred_at,known_at=trigger$known_at,dependencies=list(list(type=stype,id=sid)),payload=list(contractual_payment_status='DELAYED'));updated<-apply_assessment_event(NULL,event,dependency,'2024-01-16')$value;duplicate<-apply_assessment_event(updated$state,event,dependency,'2024-01-16')$value
 cohort<-do.call(build_monitoring_cohorts,case$cohort_input)$value;monitoring<-monitor_rating_cohort(cohort,group_by='cohort',reference_window=list(start=D,end='2024-01-31'),minimum_count=4,uncertainty='none')$value;immature_args<-case$cohort_input;immature_args$evaluation_cutoff<-'2024-01-15';immature<-do.call(build_monitoring_cohorts,immature_args)$value;permutations<-list();for(a in 0:3)for(b in setdiff(0:3,a))for(c in setdiff(0:3,c(a,b)))for(d in setdiff(0:3,c(a,b,c)))permutations[[length(permutations)+1L]]<-list(a,b,c,d);feature_drift<-detect_credit_feature_drift(list(list(x=0),list(x=1)),list(list(x=2),list(x=3)),feature_order='x',method='ks',permutations=do.call(rbind,lapply(permutations,unlist)),multiple_testing='none',dependence_assumption='exchangeable_rows')$value
 residuals<-list(list(time='2024-02-01',value=monitoring[[1]]$metrics$calibration_error,mature=TRUE));null_spec<-list(model_id=model$model_id,model_version='v1',calibration_id='zero-variation-analytical-reference',residual_scale='observed_minus_expected_rate',dependence='prespecified_dependent',probability_measure='PHYSICAL',calibrated_before='2024-01-31',validation_paths_independent=TRUE);calibration_drift<-detect_pd_calibration_drift(residuals,method='ewma',parameters=list(smoothing=.5),null_paths=matrix(0,19,1),null_spec=null_spec,alpha=.05,validation_null_paths=matrix(0,20,1))$value
 exit_args<-case$cohort_input;entity<-exit_args$predictions[[1]]$entity_id;exit_args$outcome_events<-c(exit_args$outcome_events,list(list(event_id=paste0(product,'-sale'),entity_id=entity,event_at='2024-01-15',known_at='2024-01-16',event='exit',default_definition=exit_args$target_contract$default_definition)));after<-exit_args$predictions[[1]];after$forecast_id<-paste0(product,'-after-sale');after$case_id<-paste0(product,'-after-sale');after$forecast_at<-'2024-02-01';after$known_at<-'2024-02-01';exit_args$predictions<-c(exit_args$predictions,list(after));exit_cohort<-do.call(build_monitoring_cohorts,exit_args)$value
 transitions<-list(list(from_state='DRAFT',to_state='FINAL',event_type='approve',required_gates=list('local_review')),list(from_state='FINAL',to_state='SUPERSEDED',event_type='close',required_gates=list('position_closed')));approved<-transition_assessment_state(assessment,list(event_id='approved',type='approve',occurred_at='2024-01-02',known_at='2024-01-02',reason='Synthetic local review',gates=list(local_review=TRUE)),transitions)$value;retired<-transition_assessment_state(approved,list(event_id='closed',type='close',occurred_at='2024-05-01',known_at='2024-05-01',reason='Workout settled; main claim assessment superseded',gates=list(position_closed=TRUE)),transitions)$value;newer<-model;newer$model_version<-'v2';newer$parameters$coefficients[[1]]<-10;later<-register_rating_model_version(registry,list(model=newer,dependencies=setNames(list(),character()),configuration=setNames(list(),character())),list(model_id=model$model_id,model_version='v2',registered_at='2024-02-01'))$value;replay<-replay_assessment_history(list(request),later,batch$rows,D)$value
 out[[product]]<-list(source_recipe_reference=case$source_recipe_reference,subjects=subjects,route=route,applicability=applicability,registry=registry,selected=selected,batch=batch,assessment=assessment,performing_assessment=performing_assessment,policy=policy,decision=decision,failed_legal_gate=blocked,freshness=fresh,triggered_freshness=stale,event=updated,duplicate_event=duplicate,cohort=cohort,monitoring=monitoring,immature_cohort=immature,feature_drift=feature_drift,calibration_drift=calibration_drift,exit_cohort=exit_cohort,retired=retired,replay=replay)
 }
 if(verify_reference)for(product in names(out)){r<-out[[product]];stopifnot(r$decision$action=='APPROVE',r$failed_legal_gate$action=='REFER',r$applicability$status=='APPLICABLE',r$selected$status=='SELECTED',r$freshness$status=='CURRENT',r$triggered_freshness$status=='STALE',identical(r$event$affected_assessment_ids,list(r$assessment$assessment_id)),r$duplicate_event$status=='DUPLICATE');m<-r$monitoring[[1]]$metrics;stopifnot(m$observed_rate==.5,m$brier==.25,!any(vapply(r$immature_cohort$rows,function(x)x$eligible,logical(1))),r$exit_cohort$rows[[1]]$status=='CENSORED',tail(r$exit_cohort$rows,1)[[1]]$status=='EXITED_BEFORE_FORECAST',r$feature_drift[[1]]$statistic==1,abs(r$feature_drift[[1]]$p_value-9/25)<1e-12,identical(unlist(r$calibration_drift$statistic_path),0),r$retired$state=='SUPERSEDED',length(r$retired$history)==2,r$replay$status=='REPRODUCED')}
 list(data_origin=data$data_origin,version=data$version,product=data$product,variants=out)
}
